namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        private System.Text.StringBuilder _stringBuffer;

        private void Awake()
        {
            _stringBuffer = new System.Text.StringBuilder(256);
        }

        private void Update()
        {
            _stringBuffer.Clear();
            _stringBuffer.Append("Status do Sistema: Otimizado sem alocação de GC");
        }
    }
}","explicacao_didatica":"O método Update roda a cada quadro do jogo (60 vezes por segundo). Quando instanciamos objetos, criamos novas listas ou fazemos concatenação de strings dentro do Update, o Unity aloca memória no Heap temporário. Quando essa memória enche, o C# ativa o Garbage Collector (GC) para limpar os resíduos, o que congela a execução do jogo (stuttering). Para corrigir, movemos todas as alocações para o Awake/Start e reutilizamos a memória pré-alocada."}],"dicas_level_design":null}

